<?php
$facts = array_pad(array_slice((array) ($popup['facts'] ?? []), 0, 3), 3, []);
$activeLocale = (string) ($_GET['lang'] ?? ($languages[0]['locale'] ?? 'en'));
$popupDefaultLanguage = array_values(array_filter((array) $languages, static fn(array $language): bool => (bool) ($language['is_default'] ?? false)))[0] ?? ($languages[0] ?? ['locale' => 'en']);
$popupSelectedPage = null;
foreach ($pages as $page) {
    if ((int) ($page['id'] ?? 0) === (int) $selected) {
        $popupSelectedPage = $page;
        break;
    }
}
$popupSelectedPage ??= $pages[0] ?? ['slug' => ''];
$contentWorkspace = [
    'pages' => $pages,
    'selected' => $selected,
    'select' => 'popup',
    'form' => 'page-popup-form',
    'icon' => 'panel-top-open',
    'label' => 'Target page',
    'status' => 'Saved',
    'action' => 'Save pop-up',
    'preview_url' => '/' . rawurlencode((string) $popupDefaultLanguage['locale']) . '/' . rawurlencode((string) ($popupSelectedPage['slug'] ?? '')),
];
require __DIR__ . '/console-content-workspace-header.php';
?>
