 class="sensecms-shared-settings"><header><span>SHARED SETTINGS</span><h4>Behaviour and destination</h4></header><div class="grid gap-4 md:grid-cols-2"><label><span>Action URL</span><input class="form-input" name="popup_cta_url" value="<?= $escape($popup['cta_url']??'') ?>"></label><label><span>Display frequency</span><select class="form-input" name="popup_frequency"><?php foreach(['session'=>'Once per browser session','once'=>'Once per browser','always'=>'Every visit']as$value=>$label): ?><option value="<?= $value ?>" <?= ($popup['frequency']??'session')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label><span>Show from</span><input class="form-input" type="datetime-local" name="popup_start_at" value="<?= $escape($popup['start_at']??'') ?>"></label><label><span>Show until</span><input class="form-input" type="datetime-local" name="popup_end_at" value="<?= $escape($popup['end_at']??'') ?>"></label></div></section></div></section>
